    "dataConferencia": "2026-10-31",
    "provaBloco": "P1_BASICOS",
    "versao_correta": "A participação do Colégio de Líderes na coordenação não institui veto geral a qualquer inclusão de matéria na pauta pelo Presidente.",
    "gatilho": "impedindo",
