    "gatilho": "maiúsculas integrais",
    "fonte": "ABNT NBR 10520:2023 — Citações em documentos — 6.1.1.1: pessoa física. Fonte no acervo de estudos do HNC.",
    "dataConferencia": "2026-10-31",
